function inventory_control_payload(PDO $pdo,array $scope):array
{
    v2_require_permission($scope,'inventory.control.view',['warehouse_keeper','technician'],'مشاهده کنترل‌های انبار مجاز نیست.');
    $hotWhere='h.shop_id=:shop AND h.branch_id=:branch';$hotParams=['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']];if($scope['role']==='technician'){$hotWhere.=' AND h.technician_user_id=:actor';$hotParams['actor']=$scope['actor']['id'];}
    $hot=$pdo->prepare("SELECT h.*,i.item_code,i.title AS item_title,c.receipt_number,u.display_name AS technician_name FROM repair_hot_returns h INNER JOIN repair_inventory_items i ON i.id=h.item_id INNER JOIN repair_cases c ON c.id=h.case_id INNER JOIN tamiran_users u ON u.id=h.technician_user_id WHERE {$hotWhere} ORDER BY h.updated_at DESC LIMIT 500");$hot->execute($hotParams);
    if($scope['role']==='technician')return['hotReturns'=>$hot->fetchAll(),'adjustments'=>[],'stocktakes'=>[],'stocktakeItems'=>[],'transfers'=>[]];
    $adjustments=$pdo->prepare('SELECT a.*,i.item_code,i.title AS item_title FROM repair_inventory_adjustments a INNER JOIN repair_inventory_items i ON i.id=a.item_id WHERE a.shop_id=:shop AND a.branch_id=:branch ORDER BY a.created_at DESC LIMIT 500');$adjustments->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);
    $stocktakes=$pdo->prepare('SELECT s.*,w.title AS warehouse_title,u.display_name AS creator_name FROM repair_stocktakes s INNER JOIN repair_warehouses w ON w.id=s.warehouse_id INNER JOIN tamiran_users u ON u.id=s.created_by_user_id WHERE s.shop_id=:shop AND s.branch_id=:branch ORDER BY s.created_at DESC LIMIT 100');$stocktakes->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$stocktakeRows=$stocktakes->fetchAll();
    $stocktakeItems=[];if($stocktakeRows!==[]){$ids=array_map(static fn(array $row):int=>(int)$row['id'],$stocktakeRows);$placeholders=implode(',',array_fill(0,count($ids),'?'));$items=$pdo->prepare("SELECT si.*,s.public_id AS stocktake_public_id,i.item_code,i.title AS item_title FROM repair_stocktake_items si INNER JOIN repair_stocktakes s ON s.id=si.stocktake_id INNER JOIN repair_inventory_items i ON i.id=si.item_id WHERE si.stocktake_id IN ({$placeholders}) ORDER BY si.stocktake_id DESC,i.title");$items->execute($ids);$stocktakeItems=$items->fetchAll();}
    $transfers=$pdo->prepare('SELECT t.*,fb.name AS from_branch_name,tb.name AS to_branch_name FROM repair_stock_transfers t INNER JOIN repair_branches fb ON fb.id=t.from_branch_id INNER JOIN repair_branches tb ON tb.id=t.to_branch_id WHERE t.shop_id=:shop AND (t.from_branch_id=:branch OR t.to_branch_id=:branch2) ORDER BY t.requested_at DESC LIMIT 500');$transfers->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'branch2'=>$scope['branch_id']]);return['hotReturns'=>$hot->fetchAll(),'adjustments'=>$adjustments->fetchAll(),'stocktakes'=>$stocktakeRows,'stocktakeItems'=>$stocktakeItems,'transfers'=>$transfers->fetchAll()];
}

function inventory_hot_submit(PDO $pdo,array $scope,array $input):array
{
    $public=v2_text($input['hotReturnPublicId']??'','تعهد داغی',80);$pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT h.*,i.hot_evidence_rules_json FROM repair_hot_returns h INNER JOIN repair_inventory_items i ON i.id=h.item_id WHERE h.public_id=:public AND h.shop_id=:shop AND h.branch_id=:branch AND h.status IN ('pending_return','rejected') FOR UPDATE");$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$hot=$statement->fetch();if(!is_array($hot))throw new TamiranApiException('تعهد داغی قابل تحویل نیست.',409);if($scope['role']!=='repair_manager'&&(int)$hot['technician_user_id']!==(int)$scope['actor']['id'])throw new TamiranApiException('فقط تکنسین متعهد می‌تواند داغی را تحویل دهد.',403);$rules=json_decode((string)$hot['hot_evidence_rules_json'],true)?:[];$serial=v2_text($input['serialNumber']??'','سریال',190,false);$image=(int)($input['imageFileId']??0)?:null;$condition=(string)($input['condition']??'');if(!in_array($condition,['healthy','damaged','unknown'],true))throw new TamiranApiException('سلامت داغی مشخص نشده است.');if(!empty($rules['serial'])&&$serial===null)throw new TamiranApiException('ثبت سریال این داغی الزامی است.');if(!empty($rules['image'])&&$image===null)throw new TamiranApiException('ثبت تصویر این داغی الزامی است.');$pdo->prepare('INSERT INTO repair_hot_return_evidence(hot_return_id,serial_number,condition_code,image_file_id,notes,submitted_by_user_id) VALUES(:hot,:serial,:condition,:image,:notes,:actor)')->execute(['hot'=>$hot['id'],'serial'=>$serial,'condition'=>$condition,'image'=>$image,'notes'=>v2_text($input['notes']??'','توضیحات',2000,false),'actor'=>$scope['actor']['id']]);$pdo->prepare("UPDATE repair_hot_returns SET status='waiting_review',updated_at=NOW() WHERE id=:id")->execute(['id'=>$hot['id']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'hot_return.submit','repair_hot_return',$public,['status'=>$hot['status']],['status'=>'waiting_review','serial'=>$serial,'condition'=>$condition]);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['submitted'=>true];
}

function inventory_hot_review(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.hot_return.review',['warehouse_keeper'],'بررسی داغی فقط برای انباردار یا مدیر مجاز است.');
    $public=v2_text($input['hotReturnPublicId']??'','تعهد داغی',80);
    $decision=(string)($input['decision']??'');
    if(!in_array($decision,['accept','reject'],true))throw new TamiranApiException('تصمیم معتبر نیست.');
    $reason=v2_text($input['reason']??'','علت',1000,$decision==='reject');
    $pdo->beginTransaction();
    try{
        $statement=$pdo->prepare("SELECT * FROM repair_hot_returns WHERE public_id=:public AND shop_id=:shop AND branch_id=:branch AND status='waiting_review' FOR UPDATE");
        $statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);
        $hot=$statement->fetch();
        if(!is_array($hot))throw new TamiranApiException('داغی قابل بررسی نیست.',409);
        $status=$decision==='accept'?'settled':'rejected';
        $pdo->prepare('UPDATE repair_hot_returns SET status=:status,notes=CONCAT(COALESCE(notes,\'\'),:notes),updated_at=NOW() WHERE id=:id')->execute(['status'=>$status,'notes'=>$reason===null?'':"\n".$reason,'id'=>$hot['id']]);
        $pdo->prepare('UPDATE repair_hot_return_evidence SET reviewed_by_user_id=:actor,rejection_reason=:reason WHERE hot_return_id=:hot ORDER BY id DESC LIMIT 1')->execute(['actor'=>$scope['actor']['id'],'reason'=>$decision==='reject'?$reason:null,'hot'=>$hot['id']]);
        tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'hot_return.review','repair_hot_return',$public,['status'=>$hot['status']],['status'=>$status],$reason);
        if($decision==='reject')v2_notify($pdo,$scope,(int)$hot['technician_user_id'],'hot_return_rejected','داغی تحویلی رد شد',$reason??'نیازمند تحویل مجدد','repair_hot_return',$public);
        $pdo->commit();
    }catch(Throwable$error){
        if($pdo->inTransaction())$pdo->rollBack();
        throw$error;
    }
    $routed=$decision==='accept'?v2_route_after_parts($pdo,$scope,(int)$hot['case_id'],'hot-return:'.$public):false;
    return['reviewed'=>true,'status'=>$status,'routed'=>$routed];
}

function inventory_adjustment(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.adjustment.create',['warehouse_keeper'],'ثبت سند اصلاح موجودی مجاز نیست.');$delta=(int)($input['quantityDelta']??0);if($delta===0)throw new TamiranApiException('مغایرت نمی‌تواند صفر باشد.');$public=tamiran_id();$pdo->prepare("INSERT INTO repair_inventory_adjustments(public_id,shop_id,branch_id,warehouse_id,item_id,quantity_delta,reason,status,created_by_user_id) VALUES(:public,:shop,:branch,:warehouse,:item,:delta,:reason,'awaiting_manager',:actor)")->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'warehouse'=>(int)($input['warehouseId']??0),'item'=>(int)($input['itemId']??0),'delta'=>$delta,'reason'=>v2_text($input['reason']??'','علت اصلاح',1000),'actor'=>$scope['actor']['id']]);return['created'=>true,'publicId'=>$public];
}

function inventory_adjustment_decide(PDO $pdo,array $scope,array $input):array
{
    if($scope['role']!=='repair_manager')throw new TamiranApiException('تأیید سند اصلاح فقط برای مدیر مجاز است.',403);$public=v2_text($input['publicId']??'','سند اصلاح',80);$decision=(string)($input['decision']??'');if(!in_array($decision,['approve','reject'],true))throw new TamiranApiException('تصمیم معتبر نیست.');$pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT a.*,s.operation_mode FROM repair_inventory_adjustments a INNER JOIN repair_shops s ON s.id=a.shop_id WHERE a.public_id=:public AND a.shop_id=:shop AND a.branch_id=:branch AND a.status='awaiting_manager' FOR UPDATE");$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$adjustment=$statement->fetch();if(!is_array($adjustment))throw new TamiranApiException('سند قابل تصمیم نیست.',409);$reason=v2_text($input['reason']??'','علت تصمیم',1000,(int)$adjustment['created_by_user_id']===(int)$scope['actor']['id']);if((int)$adjustment['created_by_user_id']===(int)$scope['actor']['id']&&$adjustment['operation_mode']==='multi_user')throw new TamiranApiException('در حالت چندنفره ثبت‌کننده نمی‌تواند سند خودش را تأیید کند.',409);$status=$decision==='approve'?'approved':'rejected';if($decision==='approve')v2_stock_mutate($pdo,$scope,(int)$adjustment['warehouse_id'],(int)$adjustment['item_id'],(int)$adjustment['quantity_delta'],0,'adjustment','inventory_adjustment',$public,$adjustment['reason']);$pdo->prepare('UPDATE repair_inventory_adjustments SET status=:status,approved_by_user_id=:actor,decided_at=NOW() WHERE id=:id')->execute(['status'=>$status,'actor'=>$scope['actor']['id'],'id'=>$adjustment['id']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'inventory.adjustment.'.$status,'repair_inventory_adjustment',$public,['status'=>'awaiting_manager'],['status'=>$status],$reason);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['decided'=>true,'status'=>$status];
}

function inventory_stocktake_start(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.stocktake.create',['warehouse_keeper'],'شروع انبارگردانی مجاز نیست.');$warehouseId=(int)($input['warehouseId']??0);$reason=v2_text($input['reason']??'انبارگردانی دوره‌ای','علت',1000);$pdo->beginTransaction();try{$warehouse=$pdo->prepare('SELECT id FROM repair_warehouses WHERE id=:warehouse AND shop_id=:shop AND branch_id=:branch AND is_main=1 AND is_active=1 FOR UPDATE');$warehouse->execute(['warehouse'=>$warehouseId,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);if($warehouse->fetchColumn()===false)throw new TamiranApiException('انبار اصلی شعبه پیدا نشد.',404);$active=$pdo->prepare("SELECT id FROM repair_stocktakes WHERE warehouse_id=:warehouse AND status IN ('draft','counting','awaiting_manager') FOR UPDATE");$active->execute(['warehouse'=>$warehouseId]);if($active->fetchColumn()!==false)throw new TamiranApiException('برای این انبار یک انبارگردانی باز وجود دارد.',409);$stock=$pdo->prepare('SELECT item_id,physical_quantity FROM repair_branch_stock WHERE shop_id=:shop AND branch_id=:branch AND warehouse_id=:warehouse ORDER BY item_id FOR UPDATE');$stock->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'warehouse'=>$warehouseId]);$rows=$stock->fetchAll();if($rows===[])throw new TamiranApiException('برای این انبار کالایی تعریف نشده است.',409);$public=tamiran_id();$pdo->prepare("INSERT INTO repair_stocktakes(public_id,shop_id,branch_id,warehouse_id,status,snapshot_at,created_by_user_id,reason) VALUES(:public,:shop,:branch,:warehouse,'counting',NOW(),:actor,:reason)")->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'warehouse'=>$warehouseId,'actor'=>$scope['actor']['id'],'reason'=>$reason]);$stocktakeId=(int)$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO repair_stocktake_items(stocktake_id,item_id,snapshot_quantity) VALUES(:stocktake,:item,:quantity)');foreach($rows as$row)$insert->execute(['stocktake'=>$stocktakeId,'item'=>$row['item_id'],'quantity'=>$row['physical_quantity']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'stocktake.start','repair_stocktake',$public,null,['warehouseId'=>$warehouseId,'itemCount'=>count($rows),'snapshotAt'=>'database_now'],$reason);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['created'=>true,'publicId'=>$public,'itemCount'=>count($rows)];
}

function inventory_stocktake_lock_item(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.stocktake.count',['warehouse_keeper'],'شمارش انبار مجاز نیست.');$public=v2_text($input['publicId']??'','انبارگردانی',80);$itemId=(int)($input['itemId']??0);$pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT si.*,s.warehouse_id FROM repair_stocktake_items si INNER JOIN repair_stocktakes s ON s.id=si.stocktake_id WHERE s.public_id=:public AND s.shop_id=:shop AND s.branch_id=:branch AND s.status='counting' AND si.item_id=:item FOR UPDATE");$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'item'=>$itemId]);$item=$statement->fetch();if(!is_array($item))throw new TamiranApiException('قلم قابل شمارش پیدا نشد.',404);if($item['locked_until']!==null&&strtotime((string)$item['locked_until'])>time()&&(int)$item['locked_by_user_id']!==(int)$scope['actor']['id'])throw new TamiranApiException('این قلم اکنون توسط کاربر دیگری در حال شمارش است.',409);$stock=$pdo->prepare('SELECT row_version FROM repair_branch_stock WHERE warehouse_id=:warehouse AND item_id=:item FOR UPDATE');$stock->execute(['warehouse'=>$item['warehouse_id'],'item'=>$itemId]);if($stock->fetchColumn()===false)throw new TamiranApiException('موجودی قلم پیدا نشد.',404);$until=date('Y-m-d H:i:s',time()+300);$pdo->prepare('UPDATE repair_stocktake_items SET locked_by_user_id=:actor,locked_until=:until WHERE id=:id')->execute(['actor'=>$scope['actor']['id'],'until'=>$until,'id'=>$item['id']]);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['locked'=>true,'lockedUntil'=>$until];
}

function inventory_stocktake_count_item(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.stocktake.count',['warehouse_keeper'],'شمارش انبار مجاز نیست.');$public=v2_text($input['publicId']??'','انبارگردانی',80);$itemId=(int)($input['itemId']??0);$counted=(int)($input['countedQuantity']??-1);if($counted<0)throw new TamiranApiException('تعداد شمارش‌شده معتبر نیست.');$pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT si.*,s.warehouse_id FROM repair_stocktake_items si INNER JOIN repair_stocktakes s ON s.id=si.stocktake_id WHERE s.public_id=:public AND s.shop_id=:shop AND s.branch_id=:branch AND s.status='counting' AND si.item_id=:item FOR UPDATE");$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'item'=>$itemId]);$item=$statement->fetch();if(!is_array($item))throw new TamiranApiException('قلم قابل شمارش پیدا نشد.',404);if((int)$item['locked_by_user_id']!==(int)$scope['actor']['id']||$item['locked_until']===null||strtotime((string)$item['locked_until'])<time())throw new TamiranApiException('قفل شمارش منقضی شده است؛ قلم را دوباره باز کنید.',409);$stock=$pdo->prepare('SELECT physical_quantity FROM repair_branch_stock WHERE warehouse_id=:warehouse AND item_id=:item FOR UPDATE');$stock->execute(['warehouse'=>$item['warehouse_id'],'item'=>$itemId]);if($stock->fetchColumn()===false)throw new TamiranApiException('موجودی قلم پیدا نشد.',404);$pdo->prepare('UPDATE repair_stocktake_items SET counted_quantity=:counted,counted_by_user_id=:actor,counted_at=NOW(),notes=:notes,locked_by_user_id=NULL,locked_until=NULL WHERE id=:id')->execute(['counted'=>$counted,'actor'=>$scope['actor']['id'],'notes'=>v2_text($input['notes']??'','توضیحات شمارش',1000,false),'id'=>$item['id']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'stocktake.item.count','repair_stocktake',$public,['itemId'=>$itemId,'counted'=>$item['counted_quantity']],['itemId'=>$itemId,'counted'=>$counted]);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['counted'=>true];
