function inventory_stocktake_submit(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.stocktake.count',['warehouse_keeper'],'ارسال انبارگردانی مجاز نیست.');$public=v2_text($input['publicId']??'','انبارگردانی',80);$pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT * FROM repair_stocktakes WHERE public_id=:public AND shop_id=:shop AND branch_id=:branch AND status='counting' FOR UPDATE");$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$stocktake=$statement->fetch();if(!is_array($stocktake))throw new TamiranApiException('انبارگردانی قابل ارسال نیست.',409);$pending=$pdo->prepare('SELECT COUNT(*) FROM repair_stocktake_items WHERE stocktake_id=:stocktake AND counted_quantity IS NULL');$pending->execute(['stocktake'=>$stocktake['id']]);if((int)$pending->fetchColumn()>0)throw new TamiranApiException('شمارش همه اقلام باید تکمیل شود.',409);$pdo->prepare("UPDATE repair_stocktakes SET status='awaiting_manager' WHERE id=:id")->execute(['id'=>$stocktake['id']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'stocktake.submit','repair_stocktake',$public,['status'=>'counting'],['status'=>'awaiting_manager']);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['submitted'=>true];
