function inventory_stocktake_decide(PDO $pdo,array $scope,array $input):array
{
    if($scope['role']!=='repair_manager')throw new TamiranApiException('تأیید انبارگردانی فقط برای مدیر مجاز است.',403);$public=v2_text($input['publicId']??'','انبارگردانی',80);$decision=(string)($input['decision']??'');if(!in_array($decision,['approve','cancel'],true))throw new TamiranApiException('تصمیم انبارگردانی معتبر نیست.');$pdo->beginTransaction();try{$statement=$pdo->prepare("SELECT s.*,sh.operation_mode FROM repair_stocktakes s INNER JOIN repair_shops sh ON sh.id=s.shop_id WHERE s.public_id=:public AND s.shop_id=:shop AND s.branch_id=:branch AND s.status='awaiting_manager' FOR UPDATE");$statement->execute(['public'=>$public,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$stocktake=$statement->fetch();if(!is_array($stocktake))throw new TamiranApiException('انبارگردانی قابل تصمیم نیست.',409);$self=(int)$stocktake['created_by_user_id']===(int)$scope['actor']['id'];$reason=v2_text($input['reason']??'','علت تصمیم',1000,$self);if($self&&$stocktake['operation_mode']==='multi_user')throw new TamiranApiException('در حالت چندنفره ثبت‌کننده نمی‌تواند انبارگردانی خودش را تأیید کند.',409);$adjustments=[];if($decision==='approve'){$items=$pdo->prepare('SELECT * FROM repair_stocktake_items WHERE stocktake_id=:stocktake ORDER BY item_id FOR UPDATE');$items->execute(['stocktake'=>$stocktake['id']]);foreach($items->fetchAll()as$item){$movement=$pdo->prepare('SELECT COALESCE(SUM(physical_delta),0) FROM repair_inventory_ledger WHERE warehouse_id=:warehouse AND item_id=:item AND occurred_at>:snapshot AND occurred_at<=:counted');$movement->execute(['warehouse'=>$stocktake['warehouse_id'],'item'=>$item['item_id'],'snapshot'=>$stocktake['snapshot_at'],'counted'=>$item['counted_at']]);$expected=(int)$item['snapshot_quantity']+(int)$movement->fetchColumn();$delta=(int)$item['counted_quantity']-$expected;if($delta===0)continue;$adjustmentPublic=tamiran_id();$itemReason='مغایرت انبارگردانی '.$public.'؛ موجودی مورد انتظار هنگام شمارش '.$expected;$pdo->prepare("INSERT INTO repair_inventory_adjustments(public_id,shop_id,branch_id,warehouse_id,item_id,stocktake_id,quantity_delta,reason,status,created_by_user_id,approved_by_user_id,decided_at) VALUES(:public,:shop,:branch,:warehouse,:item,:stocktake,:delta,:reason,'approved',:creator,:approver,NOW())")->execute(['public'=>$adjustmentPublic,'shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'warehouse'=>$stocktake['warehouse_id'],'item'=>$item['item_id'],'stocktake'=>$stocktake['id'],'delta'=>$delta,'reason'=>$itemReason,'creator'=>$stocktake['created_by_user_id'],'approver'=>$scope['actor']['id']]);v2_stock_mutate($pdo,$scope,(int)$stocktake['warehouse_id'],(int)$item['item_id'],$delta,0,'stocktake','stocktake',$public,$itemReason);$adjustments[]=['itemId'=>(int)$item['item_id'],'delta'=>$delta,'publicId'=>$adjustmentPublic];}}$status=$decision==='approve'?'approved':'cancelled';$pdo->prepare('UPDATE repair_stocktakes SET status=:status,approved_by_user_id=:actor,approved_at=NOW() WHERE id=:id')->execute(['status'=>$status,'actor'=>$scope['actor']['id'],'id'=>$stocktake['id']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'stocktake.'.$status,'repair_stocktake',$public,['status'=>'awaiting_manager'],['status'=>$status,'adjustments'=>$adjustments],$reason);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['decided'=>true,'status'=>$status,'adjustments'=>$adjustments];
}

function inventory_transfer_create(PDO $pdo,array $scope,array $input):array
{
    v2_require_permission($scope,'inventory.transfer.create',['warehouse_keeper'],'ثبت انتقال مجاز نیست.');$to=(int)($input['toBranchId']??0);if($to<1||$to===$scope['branch_id'])throw new TamiranApiException('شعبه مقصد معتبر نیست.');$items=is_array($input['items']??null)?$input['items']:[];if($items===[])throw new TamiranApiException('اقلام انتقال الزامی است.');$branch=$pdo->prepare('SELECT id FROM repair_branches WHERE id=:id AND shop_id=:shop AND is_active=1');$branch->execute(['id'=>$to,'shop'=>$scope['shop_id']]);if($branch->fetchColumn()===false)throw new TamiranApiException('شعبه مقصد متعلق به این تعمیرگاه نیست.',409);$pdo->beginTransaction();try{$public=tamiran_id();$pdo->prepare("INSERT INTO repair_stock_transfers(public_id,shop_id,from_branch_id,to_branch_id,status,requested_by_user_id,reason) VALUES(:public,:shop,:from_branch,:to_branch,'requested',:actor,:reason)")->execute(['public'=>$public,'shop'=>$scope['shop_id'],'from_branch'=>$scope['branch_id'],'to_branch'=>$to,'actor'=>$scope['actor']['id'],'reason'=>v2_text($input['reason']??'','علت انتقال',1000)]);$transfer=(int)$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO repair_stock_transfer_items(transfer_id,item_id,requested_quantity) VALUES(:transfer,:item,:quantity)');foreach($items as$item){$quantity=(int)($item['quantity']??0);if($quantity<1)throw new TamiranApiException('تعداد انتقال معتبر نیست.');$insert->execute(['transfer'=>$transfer,'item'=>(int)($item['itemId']??0),'quantity'=>$quantity]);}tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'stock_transfer.create','repair_stock_transfer',$public,null,['toBranchId'=>$to]);$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['created'=>true,'publicId'=>$public];
}

function inventory_transfer_step(PDO $pdo,array $scope,array $input):array
{
    $public=v2_text($input['publicId']??'','انتقال',80);$action=(string)($input['step']??'');if(!in_array($action,['approve','send','receive','reject'],true))throw new TamiranApiException('مرحله انتقال معتبر نیست.');if($action==='approve'&&$scope['role']!=='repair_manager')throw new TamiranApiException('تأیید انتقال فقط برای مدیر مجاز است.',403);if(in_array($action,['send','receive'],true))v2_require_permission($scope,'inventory.transfer.'.$action,['warehouse_keeper'],'این مرحله انتقال مجاز نیست.');$pdo->beginTransaction();try{$statement=$pdo->prepare('SELECT * FROM repair_stock_transfers WHERE public_id=:public AND shop_id=:shop FOR UPDATE');$statement->execute(['public'=>$public,'shop'=>$scope['shop_id']]);$transfer=$statement->fetch();if(!is_array($transfer))throw new TamiranApiException('انتقال پیدا نشد.',404);$expected=['approve'=>'requested','reject'=>'requested','send'=>'approved','receive'=>'sent'][$action];if($transfer['status']!==$expected)throw new TamiranApiException('ترتیب مرحله انتقال معتبر نیست.',409);if($action==='send'&&(int)$transfer['from_branch_id']!==$scope['branch_id'])throw new TamiranApiException('ارسال باید در شعبه مبدأ ثبت شود.',403);if($action==='receive'&&(int)$transfer['to_branch_id']!==$scope['branch_id'])throw new TamiranApiException('دریافت باید در شعبه مقصد ثبت شود.',403);$items=$pdo->prepare('SELECT * FROM repair_stock_transfer_items WHERE transfer_id=:transfer FOR UPDATE');$items->execute(['transfer'=>$transfer['id']]);$rows=$items->fetchAll();if($action==='send'){$warehouse=$pdo->prepare('SELECT id FROM repair_warehouses WHERE shop_id=:shop AND branch_id=:branch AND is_main=1');$warehouse->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$warehouseId=(int)$warehouse->fetchColumn();foreach($rows as$row){$quantity=(int)$row['requested_quantity'];v2_stock_mutate($pdo,$scope,$warehouseId,(int)$row['item_id'],-$quantity,0,'transfer_out','stock_transfer',$public,'ارسال انتقال بین شعب');$pdo->prepare('UPDATE repair_stock_transfer_items SET sent_quantity=:quantity WHERE id=:id')->execute(['quantity'=>$quantity,'id'=>$row['id']]);}}elseif($action==='receive'){$warehouse=$pdo->prepare('SELECT id FROM repair_warehouses WHERE shop_id=:shop AND branch_id=:branch AND is_main=1');$warehouse->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id']]);$warehouseId=(int)$warehouse->fetchColumn();foreach($rows as$row){$quantity=(int)$row['sent_quantity'];$stock=$pdo->prepare('SELECT COUNT(*) FROM repair_branch_stock WHERE warehouse_id=:warehouse AND item_id=:item');$stock->execute(['warehouse'=>$warehouseId,'item'=>$row['item_id']]);if((int)$stock->fetchColumn()<1)$pdo->prepare('INSERT INTO repair_branch_stock(shop_id,branch_id,warehouse_id,item_id,physical_quantity,reserved_quantity,average_unit_cost) VALUES(:shop,:branch,:warehouse,:item,0,0,0)')->execute(['shop'=>$scope['shop_id'],'branch'=>$scope['branch_id'],'warehouse'=>$warehouseId,'item'=>$row['item_id']]);v2_stock_mutate($pdo,$scope,$warehouseId,(int)$row['item_id'],$quantity,0,'transfer_in','stock_transfer',$public,'دریافت انتقال بین شعب');$pdo->prepare('UPDATE repair_stock_transfer_items SET received_quantity=:quantity WHERE id=:id')->execute(['quantity'=>$quantity,'id'=>$row['id']]);}}$new=['approve'=>'approved','reject'=>'rejected','send'=>'sent','receive'=>'received'][$action];$field=['approve'=>'approved_by_user_id','send'=>'sent_by_user_id','receive'=>'received_by_user_id'][$action]??'approved_by_user_id';$time=['approve'=>'approved_at','send'=>'sent_at','receive'=>'received_at'][$action]??'approved_at';$pdo->prepare("UPDATE repair_stock_transfers SET status=:status,{$field}=:actor,{$time}=NOW() WHERE id=:id")->execute(['status'=>$new,'actor'=>$scope['actor']['id'],'id'=>$transfer['id']]);tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'stock_transfer.'.$action,'repair_stock_transfer',$public,['status'=>$expected],['status'=>$new],v2_text($input['reason']??'','علت',1000,false));$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['updated'=>true,'status'=>$new];
}

tamiran_api(static function():array{$pdo=tamiran_db();$scope=v2_scope();v2_require_capability(v2_product_policy($pdo,$scope),'inventoryPro','کنترل پیشرفته انبار فقط در حالت انبار حرفه‌ای فعال است.');$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET')return inventory_control_payload($pdo,$scope);if($method!=='POST')throw new TamiranApiException('روش درخواست مجاز نیست.',405);tamiran_require_csrf();$input=tamiran_json_body();return match((string)($input['action']??'')){'hot_submit'=>inventory_hot_submit($pdo,$scope,$input),'hot_review'=>inventory_hot_review($pdo,$scope,$input),'adjustment_create'=>inventory_adjustment($pdo,$scope,$input),'adjustment_decide'=>inventory_adjustment_decide($pdo,$scope,$input),'stocktake_start'=>inventory_stocktake_start($pdo,$scope,$input),'stocktake_lock_item'=>inventory_stocktake_lock_item($pdo,$scope,$input),'stocktake_count_item'=>inventory_stocktake_count_item($pdo,$scope,$input),'stocktake_submit'=>inventory_stocktake_submit($pdo,$scope,$input),'stocktake_decide'=>inventory_stocktake_decide($pdo,$scope,$input),'transfer_create'=>inventory_transfer_create($pdo,$scope,$input),'transfer_step'=>inventory_transfer_step($pdo,$scope,$input),default=>throw new TamiranApiException('عملیات کنترل انبار معتبر نیست.'),};});
